"""Development-only fictional finance showcase; never calls a payment provider."""
import os,sys,uuid,datetime,json,pathlib
os.environ['CLUBS_TEST_URL']=os.environ.get('CLUBS_TEST_URL','http://127.0.0.1:5080')
sys.path.insert(0,str(pathlib.Path('tests').resolve()))
from support import Client,sql
assert os.environ.get('CLUBS_DEMO_DATABASE','clubs_demo')=='clubs_demo'
def good(c,p,m='GET',d=None):
 status,b=c.req(p,m,d);assert status in (200,204),(p,status,b);return b
admin=Client();assert admin.login('admin@example.test')[0]==200;ws=good(admin,'/workspaces');w=next(w for w in ws if w['role']=='Association Super Admin' and w['association'].startswith('Global'));admin.activate(w)
org=sql('SELECT "Id" FROM "Orgs" WHERE "Code"=\'GC-006\'',database='clubs_demo');person=sql('SELECT "Id" FROM "Persons" WHERE "UserId"=(SELECT "Id" FROM "Users" WHERE "Email"=\'member@example.test\')',database='clubs_demo');reviewer=sql('SELECT "Id" FROM "Users" WHERE "Email"=\'secretary@example.test\'',database='clubs_demo')
e=next((x for x in good(admin,'/finance/entities') if x['name']=='Willow Creek Community Fund'),None)
if e and good(admin,'/finance/entities/'+e['id']+'/invoices'):print('Fictional finance showcase already exists');raise SystemExit()
e=e or good(admin,'/finance/entities','POST',{'orgId':org,'name':'Willow Creek Community Fund','country':'United States','currency':'USD','decimals':2,'address':'18 Willow Lane · Fictional demonstration','collectionAuthority':'Fictional demonstration: own club collections only'});p='/finance/entities/'+e['id'];year=datetime.date.today().year;date=datetime.date.today().isoformat();None if good(admin,p+'/settings')['periods'] else good(admin,p+'/periods','POST',{'name':str(year)+' fiscal year','startsOn':f'{year}-01-01','endsOn':f'{year}-12-31'});good(admin,p+'/grants','POST',{'userId':reviewer,'role':'Owner'});treasurer=next(r for r in good(admin,'/roles') if r['name']=='Club Treasurer');good(admin,'/assignments','POST',{'email':'secretary@example.test','roleId':treasurer['id'],'orgId':org});review=Client();review.login('secretary@example.test');rw=next(w for w in good(review,'/workspaces') if w['role']=='Club Treasurer' and w['orgId']==org and w['tenantId']==e['tenantId']);review.activate(rw)
bank=good(admin,p+'/bank-accounts','POST',{'name':'Community operating account (demo)','accountNumber':'000000007204','routingDetails':'Fictional account; no external banking connection'})
for n,(customer,total,received,purpose) in enumerate([('Maya Sen',240,120,'ClubDues'),('Community annual fund',4200,4200,'Donation'),('Greenway project sponsors',1800,900,'Sponsorship'),('Maya Sen',85,0,'Event'),('Community friends',1250,1250,'Donation')]):
 invoice=good(admin,p+'/invoices','POST',{'personId':person if customer=='Maya Sen' else None,'customer':customer,'purpose':purpose,'date':date,'dueOn':date,'key':'showcase-'+str(n),'lines':[{'description':{'ClubDues':'Annual membership · community contribution','Donation':'Community development fund','Sponsorship':'Greenway restoration sponsorship','Event':'Leadership forum registration'}[purpose],'quantity':1,'rate':str(total),'accountCode':{'ClubDues':'4000','Donation':'4200','Sponsorship':'4300','Event':'4100'}[purpose]}],'notes':'Fictional development showcase. No real funds were moved.'});good(admin,'/finance/invoices/'+invoice['id']+'/issue','POST',{})
 if received:
  pay=good(admin,p+'/payments','POST',{'personId':person if customer=='Maya Sen' else None,'payer':customer,'reference':'DEMO-COLLECTION-'+str(n),'method':'BankTransfer','currency':'USD','amount':str(received),'date':date,'key':'showcase-payment-'+str(n),'evidence':'Fictional QA bank confirmation; no real transfer'});good(review,'/finance/payments/'+pay['id']+'/verify','POST',{});good(review,'/finance/payments/'+pay['id']+'/allocate','POST',{'invoiceId':invoice['id'],'amount':str(received),'key':'showcase-allocation-'+str(n)});good(review,'/finance/payments/'+pay['id']+'/settle','POST',{'bankAccountId':bank['id'],'date':date,'fee':'0','reference':'DEMO-SETTLEMENT-'+str(n)})
good(admin,p+'/dues-plans','POST',{'name':'Community membership · annual','chargeCode':'CLUB-ANNUAL','billingOrgId':org,'purpose':'ClubDues','effectiveFrom':f'{year}-01-01','effectiveTo':f'{year}-12-31','months':12,'graceDays':30,'components':[{'description':'Annual club dues','amount':'240'}]})
good(admin,p+'/budgets','POST',{'name':'Community programs '+str(year),'kind':'Annual','startsOn':f'{year}-01-01','endsOn':f'{year}-12-31','lines':[{'description':'Neighborhood service','amount':'8500'},{'description':'Club operations','amount':'2500'}]});good(admin,p+'/pledges','POST',{'contributor':'Willow Creek business circle','kind':'Sponsorship','description':'Greenway restoration · funding pledge','amount':'3000','date':date})
pathlib.Path('test-results/phase7-demo.json').write_text(json.dumps({'entityId':e['id'],'fictional':True},indent=2));print('Created fictional financial showcase through real API workflows')
